sources=json.loads(LED.read_text(encoding='utf-8'))['sources']
logs=[json.loads(l) for l in (BASE/'access_log.jsonl').read_text().splitlines()]
def sid(file):
 url=next(x['url'] for x in logs if x.get('file')==file)
 return next(x['id'] for x in sources if x['url']==url)
def ev(file,locator,quote):
 text=(BASE/file).read_text(encoding='utf-8');assert quote in text
 return {'source_id':sid(file),'url':next(x['url'] for x in logs if x.get('file')==file),'saved_file':file,'locator':locator,'quote':quote,'access_date':'2026-10-30'}
def evidence_text(file,text,quote):
 n=sid(file);p=BASE/(file+'.evidence.txt');p.write_text(text,encoding='utf-8')
 r=subprocess.run(['python',S,'--ledger',str(LED),'quote',str(n),'--text',quote,'--from',str(p)],capture_output=True,text=True);assert r.returncode==0,r.stderr
 return n
